// vcCanonical round-trips a value through generic JSON so map keys sort
// regardless of whether the adapter returned a struct or a map.
func vcCanonical(t *testing.T, value any) string {
	t.Helper()
	raw, err := json.Marshal(value)
	if err != nil {
		t.Fatalf("failed to marshal value: %v", err)
	}
	var normalized any
	if err := json.Unmarshal(raw, &normalized); err != nil {
		t.Fatalf("failed to normalize value: %v", err)
	}
	out, err := json.Marshal(normalized)
	if err != nil {
		t.Fatalf("failed to re-marshal value: %v", err)
	}
	return string(out)
}

func vcBaseDir() string {
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		return "."
	}
	return filepath.Dir(file)
}

func vcResolveRefs(t *testing.T, value any, dir string) any {
	switch typed := value.(type) {
	case []any:
		out := make([]any, len(typed))
		for i, item := range typed {
			out[i] = vcResolveRefs(t, item, dir)
		}
		return out
	case map[string]any:
		if len(typed) == 1 {
			for key, raw := range typed {
				str, isStr := raw.(string)
				if isStr && key == "$env" {
					return os.Getenv(str)
				}
				if isStr && key == "$file" {
					data, err := os.ReadFile(filepath.Join(dir, str))
					if err != nil {
						t.Fatalf("failed to read $file %q: %v", str, err)
					}
					return string(data)
				}
				if isStr && key == "$json" {
					data, err := os.ReadFile(filepath.Join(dir, str))
					if err != nil {
						t.Fatalf("failed to read $json %q: %v", str, err)
					}
					var parsed any
					if err := json.Unmarshal(data, &parsed); err != nil {
						t.Fatalf("failed to parse $json %q: %v", str, err)
					}
					return parsed
				}
			}
		}
		out := make(map[string]any, len(typed))
		for key, item := range typed {
			out[key] = vcResolveRefs(t, item, dir)
		}
		return out
	default:
		return value
	}
}

func vcRunVector(t *testing.T, index int) {
	var vectors []map[string]any
	if err := json.Unmarshal(vectorConformancePayload, &vectors); err != nil {
		t.Fatalf("failed to decode embedded vectors: %v", err)
	}
	entry := vectors[index]
	contract, _ := entry["contract"].(string)
	operation, _ := entry["operation"].(string)
	operationKey := contract + "." + operation
	vector, _ := entry["vector"].(map[string]any)
	vectorName := "unnamed"
	if name, ok := vector["name"].(string); ok {
		vectorName = name
	}
	vectorID := operationKey + ":" + vectorName

	adapter, ok := vectoradapters.VectorAdapters[operationKey]
	if !ok {
		adapter, ok = vectoradapters.VectorAdapters[operation]
	}
	if !ok {
		waiver, hasWaiver := vectoradapters.VectorWaivers[operationKey]
		if !hasWaiver {
			waiver, hasWaiver = vectoradapters.VectorWaivers[operation]
		}
		if hasWaiver && waiver != "" {
			t.Skipf("SKIP %s (waived: %s)", vectorID, waiver)
			return
		}
		t.Fatalf("No vector adapter registered for %s. Register "+
			"VectorAdapters[%q] in the package referenced by 'vector-adapter-path', "+
			"or add an explicit waiver. @vector conformance never skips silently.",
			operationKey, operationKey)
		return
	}

	// Per-vector waiver, consulted even when an adapter IS registered. Keyed by
	// the full vector id ("Contract.operation:name") or "operation:name" so it
	// never collides with an operation-level waiver. xfail: a waived vector that
	// fails is an expected failure (green); xpass: a waived vector that passes is
	// surfaced as a hard failure so stale waivers get removed.
	vectorWaiver, vectorWaived := vectoradapters.VectorWaivers[vectorID]
	if !vectorWaived {
		vectorWaiver, vectorWaived = vectoradapters.VectorWaivers[operation+":"+vectorName]
	}
	vectorWaived = vectorWaived && vectorWaiver != ""

	// Evaluate the vector without failing the test directly: return "" on a
	// match, or a mismatch message on any failure, so the waiver decision below
	// can turn a failure into an xfail.
	mismatch := func() string {
		baseDir := vcBaseDir()
		provider, _ := vector["provider"].(string)
		targetAPI, _ := vector["targetApi"].(string)
		ctx := vectoradapters.Context{
			Contract:  contract,
			Operation: operation,
			Vector:    vector,
			Provider:  provider,
			TargetAPI: targetAPI,
			Doubles:   vectoradapters.VectorDoubles,
			BaseDir:   baseDir,
		}
		input := vcResolveRefs(t, vector["input"], baseDir)
		normalize := adapter.Normalize
		if normalize == nil {
			normalize = func(value any, _ vectoradapters.Context) any { return value }
		}

		if _, isError := vector["expectedError"]; isError {
			_, err := adapter.Invoke(input, ctx)
			if err == nil {
				return fmt.Sprintf("%s: expected the adapter to signal an error, but it returned a value.", vectorID)
			}
			var observed any
			if carrier, ok := err.(interface{ TypraVector() any }); ok {
				observed = carrier.TypraVector()
			} else {
				observed = map[string]any{"message": err.Error()}
			}
			got := vcCanonical(t, normalize(observed, ctx))
			want := vcCanonical(t, vector["expectedError"])
			if got != want {
				return fmt.Sprintf("%s error mismatch\n want %s\n got  %s", vectorID, want, got)
			}
			return ""
		}

		observed, err := adapter.Invoke(input, ctx)
		if err != nil {
			return fmt.Sprintf("%s: adapter returned an unexpected error: %v", vectorID, err)
		}
		got := vcCanonical(t, normalize(observed, ctx))
		want := vcCanonical(t, vector["expected"])
		if got != want {
			return fmt.Sprintf("%s mismatch\n want %s\n got  %s", vectorID, want, got)
		}
		return ""
	}()

	if vectorWaived {
		if mismatch != "" {
			t.Logf("XFAIL %s (waived: %s)", vectorID, vectorWaiver)
			return
		}
		t.Fatalf("XPASS %s: waived vector unexpectedly passed; remove the waiver (%s)", vectorID, vectorWaiver)
		return
	}
	if mismatch != "" {
		t.Fatalf("%s", mismatch)
	}
}

